      bulkNoPoint3: 'Продолжить без точки восстановления можно только по явному согласию — панель спрашивает отдельно и предупреждает, что откатывать будет нечем.',
      bulkNote: 'Предпросмотр удаления таблицы и удаления базы устроен так же: сначала показывается, сколько строк исчезнет или сколько таблиц в базе, и ничего не удаляется до подтверждения.',
      sqlH3: 'SQL-редактор',
      sqlP: 'Редактор доступен на верхнем уровне (вкладка «SQL») и внутри карточки таблицы. Это текстовое поле с подсветкой синтаксиса SQL, тёмной темой и моноширинным шрифтом.',
      sqlBoxButtons: 'Кнопки и поведение',
      sqlButtons1: '«Выполнить» — отправляет текст в выбранную базу данных.',
