      sqlPlan1: 'Кнопка «Объяснить» рядом с «Выполнить» показывает, как СУБД выполнит запрос: индексы, сканирование, стоимость, а в PostgreSQL с анализом — фактические тайминги.',
      sqlPlan2: 'Объяснить можно только чтение: запросы записи (INSERT, UPDATE, DELETE, DDL) отклоняются, потому что анализ с таймингами в PostgreSQL выполняет запрос по-настоящему.',
      sqlPlan3: 'Поддерживают MySQL, MariaDB, PostgreSQL и SQLite. У MongoDB и Redis планировщика нет — панель сообщит об этом.',
