      sqlHistory4: 'В журнале запрос можно скопировать, отправить в редактор или выполнить повторно.',
      sqlHistory5: 'Параллельно пишется аудит: действие, цель, успех, длительность, автор.',
      sqlHistory6: 'Журналы можно очистить: кнопка «Очистить» в панели «Журналы» — на вкладке «Последние операции» стирается своя история запросов, на вкладке «События» (только администратор) — журнал операций, на вкладке «SQL» — список текущей сессии. Для администратора доступна полная очистка записей всех пользователей, а также отдельно — только сохранённых запросов.',
