      transferExport6: 'В списке «Что выгружать» можно выбрать не одну таблицу, а всю базу сразу: получится один файл. Порядок таблиц в SQL-дампе выстраивается по внешним ключам, сначала родители, поэтому дамп можно восстановить в новой базе без ошибок порядка. CSV всей базы составной: каждая таблица начинается со строки «# table: имя», чтобы файл можно было разделить обратно.',
