      zeroDate: 'La fecha cero no se permite: MySQL 8.4 y MariaDB 10.2+ funcionan con NO_ZERO_DATE y STRICT_TRANS_TABLES, así que 0000-00-00 00:00:00 ya no es válido ni como valor ni como DEFAULT. Usa una fecha real como 1970-01-01 00:00:00, permite NULL en la columna o relaja sql_mode para la sesión.',
