function isPlainObject(value: unknown): value is Record<string, any> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const LANGS = ['ru', 'en', 'de', 'fr', 'es', 'zh'] as const;

/** «Сумка языков» — значение, записанное сразу для всех языков:
 * title: { ru: 'Таблицы', en: 'Tables', … }. Их много в additions.
 * Если такую сумку слить как обычный вложенный объект, в переводах окажется
 * объект вместо строки, и t() вернёт сам ключ: пользователь увидит в панели
 * «panels.tables» вместо «Таблицы». Поэтому сумку разворачиваем в текущий язык. */
function isLangBag(value: unknown): value is Record<string, string> {
  if (!isPlainObject(value)) return false;
  const keys = Object.keys(value);
  return keys.length > 0 && keys.every(key => (LANGS as readonly string[]).includes(key));
}

function deepMerge<T extends Record<string, any>>(target: T, source: Record<string, any>, lang: string): T {
  const result: Record<string, any> = { ...target };
  for (const [key, value] of Object.entries(source)) {
    if (isLangBag(value)) {
      // Сумка языков: берём строку текущего языка, иначе при нехватке языка —
      // русский, чтобы панель не осталась с английским текстом.
      result[key] = value[lang] ?? value.ru ?? Object.values(value)[0];
    } else if (isPlainObject(value)) {
      // Заходим в объект ВСЕГДА, даже если такого раздела ещё нет в цели.
      // Иначе ветка копируется целиком вместе с вложенными сумками языков.
      result[key] = deepMerge(isPlainObject(result[key]) ? result[key] : {}, value, lang);
    } else {
      result[key] = value;
    }
  }
  return result as T;
}

for (const lang of LANGS) {
  translations[lang] = deepMerge(translations[lang] ?? {}, additions[lang] ?? {}, lang);
}
